		/** 
		 * Tests creating a new BOMItem.
		 */
		public void testCreate() throws Throwable {
			LOGGER.info( "\n======== CREATE ======== ");
			LOGGER.info( "-- Attempting to create a BOMItem");

			StringBuilder msg = new StringBuilder( "-- Failed to create a BOMItem" );

			try {            
				BOMItem entity = BOMItemService.getBOMItemInstance().createBOMItem( generateNewEntity() );
				thePrimaryKey = entity.getBOMItemId();
				LOGGER.info( "-- Successfully created a BOMItem with primary key" + thePrimaryKey );
			}
			catch (Exception e) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : " + e );

				throw e;
			}
		}

		/** 
		 * Tests reading a BOMItem. 
		 */
		public BOMItem testRead() throws Throwable {
			LOGGER.info( "\n======== READ ======== ");
			LOGGER.info( "-- Reading a previously created BOMItem" );

			BOMItem entity = null;
			StringBuilder msg = new StringBuilder( "-- Failed to read BOMItem with primary key" );
			msg.append( thePrimaryKey );
			
			BOMItemFetchOneSummary fetchOneSummary = new BOMItemFetchOneSummary( thePrimaryKey );

			try {
				entity = BOMItemService.getBOMItemInstance().getBOMItem( fetchOneSummary );

				assertNotNull( entity,msg.toString() );

				LOGGER.info( "-- Successfully found BOMItem " + entity.toString() );
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : " + e );

				throw e;
			}
			
			return entity;
		}

		/** 
		 * Tests updating a BOMItem.
		 */
		public void testUpdate() throws Throwable {
			LOGGER.info( "\n======== UPDATE ======== ");
			LOGGER.info( "-- Attempting to update a BOMItem." );

			StringBuilder msg = new StringBuilder( "Failed to update a BOMItem : " );        
			BOMItem entity = null;

			try {            
				entity = testRead();

				assertNotNull( entity, msg.toString() );

				LOGGER.info( "-- Now updating the created BOMItem." );

				// for use later on...
				thePrimaryKey = entity.getBOMItemId();

				BOMItemService proxy = BOMItemService.getBOMItemInstance();            
				proxy.updateBOMItem( entity );   

				LOGGER.info( "-- Successfully saved BOMItem - " + entity.toString() );
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : primarykey = " + thePrimaryKey + " : entity-" +  entity + " : " + e );

				throw e;
			}
		}

		/** 
		 * Tests deleting a BOMItem.
		 */
		public void testDelete() throws Throwable {
			LOGGER.info( "\n======== DELETE ======== ");
			LOGGER.info( "-- Deleting a previously created BOMItem." );

			try{
			    BOMItem entity = testRead(); 
				BOMItemService.getBOMItemInstance().delete( entity );

				LOGGER.info( "-- Successfully deleted BOMItem with primary key " + thePrimaryKey );            
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( "-- Failed to delete BOMItem with primary key " + thePrimaryKey );

				throw e;
			}
		}

		/**
		 * Tests getting all BOMItems.
		 */
		public void testGetAll() throws Throwable {    
			LOGGER.info( "======== GETALL ======== ");
			LOGGER.info( "-- Retrieving Collection of BOMItems:" );

			StringBuilder msg = new StringBuilder( "-- Failed to get all BOMItem : " );        
			List<BOMItem> collection  = null;

			try {
				// call the static get method on the BOMItemService
				collection = BOMItemService.getBOMItemInstance().getAllBOMItem();

				if ( collection == null || collection.size() == 0 ) {
					LOGGER.warning( unexpectedErrorMsg );
					LOGGER.warning( msg.toString() + " Empty collection returned."  );
				}
				else {
					// Now print out the values
					BOMItem entity = null;            
					Iterator<BOMItem> iter = collection.iterator();
					int index = 1;

					while( iter.hasNext() ) {
						// Retrieve the entity   
						entity = iter.next();

						assertNotNull( entity,"-- null entity in Collection." );
						assertNotNull( entity.getBOMItemId(), "-- entity in Collection has a null primary key" );        

						LOGGER.info( " - " + String.valueOf(index) + ". " + entity.toString() );
						index++;
					}
				}
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : " + e );

				throw e;
			}
		}

